SELECT * FROM plan_time_slots
WHERE id = #{id}
  AND deleted_at IS NULL

SELECT * FROM plan_time_slots
WHERE plan_id = #{planId}
  AND slot_date = #{slotDate}
  AND start_time = #{startTime}
  AND deleted_at IS NULL

SELECT *
FROM plan_time_slots
WHERE deleted_at IS NULL

  AND plan_id = #{planId}


  AND slot_date = #{slotDate}


  AND is_open = #{isOpen}

ORDER BY slot_date, start_time

  LIMIT #{limit}


  OFFSET #{offset}
